"""Round-3 build (POST-PILOT, PLAN 'round 3'). (1) Non-ceiling polarity test: a neutral yes/no question context (generated by terra from the A sentence, must carry no
negation) so that negation is plausible; arms ctxq_bare / ctxq_yes / ctxq_not for POL families in EN/DE/ES/FR. (2) E8-style machine meaning-check of control keyword sets.
Appends new requests to runs/frontier_multilingual_r2/requests.jsonl (idempotent, ids deduped) so queued local-model generations pick them up."""
import asyncio, sys, json, re
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
from frontier_multilingual_r2_lib import *  # noqa
import httpx

P0 = (ROOT / "prompts/P0.txt").read_text().strip()
LEG = (ROOT / "prompts/chip_legend.txt").read_text().strip()
ADDED = "Write the sentence in {lang}."
QP = ("Here is a statement in {lang}: \"{s}\"\nWrite ONE short yes/no question in {lang} that a listener could have asked, to which this statement or its opposite would be a natural answer. "
      "The question must NOT contain any negation word and must not give the answer. Return ONLY a JSON object {{\"question\": \"...\"}}.")


def render(lang, kw_line, ctx):
    t = P0
    if lang != "en":
        t = t.replace("Output only the sentence.", "Output only the sentence. " + ADDED.format(lang=LANGS[lang]))
    return t.replace("{legend}", LEG).replace("{context}", f"Situation: {ctx}\n" if ctx else "").replace("{input}", kw_line)


async def main():
    tr = jl(OUT / "translations.jsonl")
    acc = [r for r in tr if r["accepted"] and r["kind"] == "POL"]
    en_fam = {}
    for r in tr:
        if r["kind"] == "POL":
            en_fam.setdefault(r["family_id"], r)
    sem = asyncio.Semaphore(4)
    items = [("en", f, r["A"], r["bare"]) for f, r in en_fam.items()] + [(r["lang"], r["family_id"], r["t"]["A"], r["t"]["keywords"]) for r in acc]
    qs = {}
    async with httpx.AsyncClient() as c:
        async def one(it):
            lang, fam, s, kw = it
            t = await chat2(c, sem, "gpt-6.1-terra", QP.format(lang=L4[lang], s=s), 300)
            j = pj(t); q = (j or {}).get("question") if isinstance(j, dict) else None
            ok = isinstance(q, str) and q.strip() and not NEGRX[lang].search(q)
            qs[(lang, fam)] = {"question": q if ok else None, "kw": kw, "raw_ok": isinstance(q, str)}
        await asyncio.gather(*[one(i) for i in items])
    reqs = jl(RUN2 / "requests.jsonl")
    have = {q["id"] for q in reqs}
    new = []
    def add(lang, fam, arm, variant, prompt):
        q = {"id": h(lang, "POL", fam, arm, variant, "L", 0.0, 0, "r3")[:16], "lang": lang, "kind": "POL", "family_id": fam, "arm": arm, "variant": variant, "pset": "L", "temp": 0.0, "draw": 0,
             "prompt": prompt, "prompt_sha": h(prompt)[:12]}
        if q["id"] not in have:
            new.append(q); have.add(q["id"])
    for (lang, fam), d in sorted(qs.items()):
        if not d["question"]:
            continue
        ctx = f"The listener just asked: \"{d['question']}\""
        add(lang, fam, "ctxq_bare", "AB", render(lang, f"Keywords: {d['kw']}", ctx))
        add(lang, fam, "ctxq_yes", "A", render(lang, f"Keywords: [YES] {d['kw']}", ctx))
        add(lang, fam, "ctxq_not", "B", render(lang, f"Keywords: [NOT] {d['kw']}", ctx))
        # added 2026-11-02 after the question-context arms showed 0% negation for terra (declared in PLAN before these were generated): refusal prior
        ctxn = ctx + " The user is answering with a refusal."
        add(lang, fam, "ctxn_bare", "AB", render(lang, f"Keywords: {d['kw']}", ctxn))
        add(lang, fam, "ctxn_yes", "A", render(lang, f"Keywords: [YES] {d['kw']}", ctxn))
    with open(RUN2 / "requests.jsonl", "a") as f:
        for q in new:
            f.write(json.dumps(q, ensure_ascii=False) + "\n")
    json.dump({f"{k[0]}|{k[1]}": v for k, v in qs.items()}, open(OUT / "r3_questions.json", "w"), ensure_ascii=False, indent=1)
    print("questions", len(qs), "usable", sum(1 for v in qs.values() if v["question"]), "new requests", len(new))

asyncio.run(main())
